import React, { useState } from 'react';

const SearchBar = ({ onAddFavorite }) => {
    const [query, setQuery] = useState('');

    // Kullanıcı enter'a veya butona bastığında çalışır
    const handleSearch = (e) => {
        e.preventDefault();
        if (!query.trim()) return;

        // MVP aşamasında gerçeğe yakın bir simülasyon için, 
        // kullanıcı ismi yazdığında bunu sahte bir ID ile ana sayfaya yolluyoruz.
        // İleriki aşamada burası doğrudan TMDB Search API'sine bağlanıp otomatik tamamlama (autocomplete) sunacaktır.
        const simulatedMovie = {
            id: Math.floor(Math.random() * 100000), // Rastgele TMDB ID'si
            title: query
        };

        onAddFavorite(simulatedMovie);
        setQuery(''); // Arama kutusunu temizle
    };

    return (
        <form onSubmit={handleSearch} style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
            <input
                type="text"
                placeholder="Sevdiğiniz bir filmi yazın..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                style={{
                    flex: 1,
                    padding: '10px 15px',
                    borderRadius: '8px',
                    border: '1px solid #ccc',
                    fontSize: '16px'
                }}
            />
            <button
                type="submit"
                style={{
                    padding: '10px 20px',
                    backgroundColor: '#007BFF',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontWeight: 'bold'
                }}
            >
                Ekle
            </button>
        </form>
    );
};

export default SearchBar;
